<?php declare(strict_types=1);use PHPUnit\Framework\TestCase;final class ToolCalculatorTest extends TestCase {public function testEveryFixtureProducesFiniteResult():void{$cases=json_decode(file_get_contents(__DIR__.'/../../fixtures/tools-calculator.json'),true);$this->assertCount(24,$cases);$calc=new ToolCalculator();foreach($cases as $case){$out=$calc->calculate($case['tool'],$case['inputs']);$this->assertSame($case['tool'],$out['tool']);$this->assertSame(1,$out['version']);array_walk_recursive($out['result'],function($v):void{if(is_float($v))$this->assertTrue(is_finite($v));});}}public function testKnownResults():void{$c=new ToolCalculator();$m=$c->calculate('markup-margin',['mode'=>'markup','percent'=>30,'cost'=>400]);$this->assertEqualsWithDelta(.230769,$m['result']['margin'],.000001);$this->assertEqualsWithDelta(520,$m['result']['price'],.001);$b=$c->calculate('break-even',['rate'=>50,'cost_per_billed_hour'=>50]);$this->assertNull($b['result']['hours']);$p=$c->calculate('mow-price',['onsite'=>10,'crew'=>1,'drive'=>5,'cost_paid'=>20,'margin'=>20,'minimum'=>55]);$this->assertTrue($p['result']['minimumApplied']);}}
